#!/bin/bash
# SPDX-License-Identifier: MIT
#
# Copy the packed phone-DSH Worker assets into the iOS probe app bundle.
#
# This is the documented build-time step for PLAN W3-APP: the app expects
# `Bundle/worker/` to contain the static www (`index.html`, `boot.js`,
# `worker-entry.js`), the full DSH Web page at `web/` (`index.html`, its
# `assets/`, the injected `web-boot.js`, and the real `web-build.json`),
# `image.tar.gz`, `lazy/` and the packer metadata. The assets are generated by
# the same verified DSH checkout and are not committed.
#
# Usage:
#   examples/probe-app/scripts/copy-bundle-assets.sh [options]
#
# Options:
#   --worker-out DIR   reuse a worker-entry build directory instead of running
#                      plugins/worker-entry/build.mjs. Without it, the checkout
#                      named by --checkout is first verified against the Web
#                      build's commit/version, so the Worker entry cannot come
#                      from a different checkout than the page and image.
#   --image-out DIR    reuse a pack-image output directory instead of running
#                      plugins/scripts/pack-image.mjs
#   --without-python   explicitly omit CPython/WASI from the app image
#   --without-jq       explicitly omit the jq WASI engine from the app image
#   --web-dist DIR     reuse a built @deepseek-ai/dsh-web-frontend dist (or an
#                      already staged Bundle/worker/web); PDSH_WEB_DIST is the
#                      environment spelling. Without it, an existing
#                      Bundle/worker/web is preserved and revalidated. The dist
#                      must carry the real web-build.json from
#                      scripts/ci/build-web-dist.sh; it is never synthesized.
#                      When no Web dist exists at all, the legacy Worker/www
#                      staging still succeeds and the full Web page is simply
#                      absent.
#   --checkout DIR     DSH checkout used when this script builds the image
#                      (default PDSH_DSH_CHECKOUT or
#                      ~/.config/phone-dsh/dsh-checkout).
#   --force            replace Bundle/worker even when the output is present
#
# Build the full DSH Web page first with:
#   bash scripts/ci/build-web-dist.sh
# (the legacy Worker smoke/app path does not require it).
# For a controlled non-pin checkout pass the same pair to the Web build, then
# this script forwards web-build.json's commit/version to pack-image:
#   bash scripts/ci/build-web-dist.sh --source "$DSH_CHECKOUT" \
#     --commit "$DSH_COMMIT" --version "$DSH_VERSION"
#   examples/probe-app/scripts/copy-bundle-assets.sh --checkout "$DSH_CHECKOUT"
#
# The staged image metadata (`sizes.json`) and Web metadata (`web-build.json`)
# must name the same commit and installation version. Missing or different
# metadata fails before Bundle/worker is replaced; no record is fabricated.
#
# The assembled `worker-entry.js` gets the same JavaScriptCore compatibility
# prelude `scripts/ci/smoke.sh` applies: the WebKit Worker's JSC lacks
# `Symbol.dispose` / `Symbol.asyncDispose` and async iteration over
# `ReadableStream` that DSH 0.2.1 relies on. See the README's known gaps.

set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
EXAMPLE="$(cd "$HERE/.." && pwd)"
ROOT="$(cd "$EXAMPLE/../.." && pwd)"
PLUGIN_DIR="$ROOT/plugins"
DEST="$EXAMPLE/Bundle/worker"

WORKER_OUT=""
IMAGE_OUT=""
WEB_DIST="${PDSH_WEB_DIST:-}"
CHECKOUT="${PDSH_DSH_CHECKOUT:-}"
FORCE=0
WITHOUT_PYTHON=0
WITHOUT_JQ=0
EXPLICIT_WORKER_OUT=0
while [ $# -gt 0 ]; do
  case "$1" in
    --worker-out) WORKER_OUT="${2:-}"; EXPLICIT_WORKER_OUT=1; shift 2 ;;
    --image-out)  IMAGE_OUT="${2:-}"; shift 2 ;;
    --without-python) WITHOUT_PYTHON=1; shift ;;
    --without-jq) WITHOUT_JQ=1; shift ;;
    --web-dist)   WEB_DIST="${2:-}"; shift 2 ;;
    --checkout)   CHECKOUT="${2:-}"; shift 2 ;;
    --force)      FORCE=1; shift ;;
    -h|--help)    sed -n '2,51p' "$0"; exit 0 ;;
    *) echo "copy-bundle-assets: unknown argument: $1" >&2; exit 2 ;;
  esac
done

# The build output directory may not exist in a clean checkout. Nothing is
# written into it until a complete staged bundle has validated: the stage lives
# beside it and is swapped in with same-directory renames.
mkdir -p "$(dirname "$DEST")"

TMP="$(mktemp -d "${TMPDIR:-/tmp}/pdsh-probe-bundle.XXXXXX")"
STAGE=""
OLD=""
cleanup() {
  # Restore the previous bundle if the process stopped between the two renames.
  if [ -n "$OLD" ] && [ ! -e "$DEST" ]; then
    mv "$OLD" "$DEST" 2>/dev/null || true
    OLD=""
  fi
  rm -rf "$TMP" "$STAGE" "$OLD"
}
trap cleanup EXIT

# One validator drives the source-dist check, the no-force existing-bundle
# check, and the post-stage record. Byte digests and boot-tag ordering are
# checked before any bundle entry is copied, not after the old one is cleared.
cat > "$TMP/verify-bundle.mjs" <<'NODE'
import { createHash } from 'node:crypto'
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const [mode, ...args] = process.argv.slice(2)
const sha = file => createHash('sha256').update(readFileSync(file)).digest('hex')

function fail(message) {
  throw new Error(message)
}

function readJson(file, what) {
  let value
  try {
    value = JSON.parse(readFileSync(file, 'utf8'))
  } catch (reason) {
    fail(`cannot read ${what} ${file}: ${reason.message}`)
  }
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    fail(`${what} ${file} must hold a JSON object`)
  }
  return value
}

function requireFile(file, what) {
  if (!existsSync(file)) fail(`missing ${what}: ${file}`)
  if (!statSync(file).isFile() || statSync(file).size === 0) {
    fail(`${what} is empty: ${file}`)
  }
}

function requireDir(dir, what) {
  if (!existsSync(dir) || !statSync(dir).isDirectory()) fail(`missing ${what}: ${dir}`)
  if (readdirSync(dir).length === 0) fail(`${what} is empty: ${dir}`)
}

function validateWeb(web) {
  const index = join(web, 'index.html')
  const assets = join(web, 'assets')
  const buildFile = join(web, 'web-build.json')
  if (!existsSync(index)) fail(`incomplete Web dist: missing ${index}`)
  if (!existsSync(assets)) fail(`incomplete Web dist: missing ${assets}`)
  if (!existsSync(buildFile)) {
    fail(`missing ${buildFile}; rebuild the Web dist with scripts/ci/build-web-dist.sh`)
  }
  const record = readJson(buildFile, 'Web build record')
  if (typeof record.commit !== 'string' || !/^[0-9a-f]{40}$/.test(record.commit)) {
    fail(`${buildFile} has no full 40-character commit; rebuild with scripts/ci/build-web-dist.sh`)
  }
  if (typeof record.dsh_version !== 'string' || record.dsh_version === '') {
    fail(`${buildFile} has no dsh_version; rebuild with scripts/ci/build-web-dist.sh`)
  }
  for (const field of ['dsh_pin_commit', 'dsh_pin_version']) {
    if (typeof record[field] !== 'string' || record[field] === '') {
      fail(`${buildFile} has no ${field}; rebuild with scripts/ci/build-web-dist.sh`)
    }
  }
  for (const field of ['entry', 'entry_sha256', 'index_sha256']) {
    if (typeof record[field] !== 'string' || record[field] === '') {
      fail(`${buildFile} has no ${field}; rebuild with scripts/ci/build-web-dist.sh`)
    }
  }
  if (!/^[0-9a-f]{64}$/.test(record.entry_sha256) || !/^[0-9a-f]{64}$/.test(record.index_sha256)) {
    fail(`${buildFile} does not carry sha256 digests`)
  }
  if (!record.entry.startsWith('assets/')) {
    fail(`${buildFile} entry is not under assets/: ${record.entry}`)
  }
  const entryPath = join(web, record.entry)
  if (!existsSync(entryPath)) {
    fail(`${buildFile} names a missing entry: ${record.entry}`)
  }
  const entrySha = sha(entryPath)
  const indexSha = sha(index)
  if (entrySha !== record.entry_sha256) {
    fail(`${web}/${record.entry} does not match web-build.json entry_sha256`)
  }
  if (indexSha !== record.index_sha256) {
    fail(`${web}/index.html does not match web-build.json index_sha256`)
  }

  const html = readFileSync(index, 'utf8')
  const boot = html.indexOf('src="./web-boot.js"')
  const ready = html.indexOf('__DSH_BOOT_READY__')
  const entryTag = html.search(/<script\b[^>]*\bsrc="\.\/assets\/[^"]+"/i)
  if (ready === -1 || boot === -1 || entryTag === -1 || ready > entryTag || boot > entryTag) {
    fail(`${web}/index.html is missing the boot-ready/web-boot injection before its Vite entry`)
  }
  for (const match of html.matchAll(/(?:src|href)="\.\/(assets\/[^"]+)"/g)) {
    if (!existsSync(join(web, match[1]))) {
      fail(`${web}/index.html references missing ${match[1]}`)
    }
  }
  return { record, entrySha, indexSha }
}

function validateImage(sizesFile) {
  if (!existsSync(sizesFile)) fail(`missing image metadata: ${sizesFile}`)
  const image = readJson(sizesFile, 'image sizes record')
  if (typeof image.dsh_commit !== 'string' || !/^[0-9a-f]{40}$/.test(image.dsh_commit)) {
    fail(`${sizesFile} has no full dsh_commit`)
  }
  if (typeof image.dsh_version !== 'string' || image.dsh_version === '') {
    fail(`${sizesFile} has no dsh_version`)
  }
  for (const field of ['dsh_pin_commit', 'dsh_pin_version', 'dsh_expected_commit', 'dsh_expected_version']) {
    if (typeof image[field] !== 'string' || image[field] === '') {
      fail(`${sizesFile} has no ${field}; repack with plugins/scripts/pack-image.mjs`)
    }
  }
  return image
}

function compare(web, image, buildFile, sizesFile) {
  if (web.commit !== image.dsh_commit) {
    fail(
      `Web dist commit ${web.commit} does not match image sizes.json dsh_commit ${image.dsh_commit};`
      + ' rebuild both from the same controlled checkout',
    )
  }
  if (web.dsh_version !== image.dsh_version) {
    fail(
      `Web dist version ${web.dsh_version} does not match image sizes.json dsh_version ${image.dsh_version};`
      + ' rebuild both from the same controlled checkout',
    )
  }
  if (web.dsh_pin_commit !== image.dsh_pin_commit || web.dsh_pin_version !== image.dsh_pin_version) {
    fail(
      'Web dist and image sizes.json record different canonical pins;'
      + ' rebuild both from the same repository pin',
    )
  }
  process.stdout.write(`copy-bundle-assets: same source ${web.commit} (${web.dsh_version})\n`)
}

function facts(web) {
  const { record } = validateWeb(web)
  process.stdout.write([
    record.commit,
    record.dsh_version,
    record.dsh_pin_commit,
    record.dsh_pin_version,
  ].join('\n') + '\n')
}

function same(web, sizesFile) {
  const { record } = validateWeb(web)
  const image = validateImage(sizesFile)
  compare(record, image, join(web, 'web-build.json'), sizesFile)
}

function probe(web, sizesFile, probeFile) {
  const { record: webRecord, entrySha, indexSha } = validateWeb(web)
  const image = validateImage(sizesFile)
  compare(webRecord, image, join(web, 'web-build.json'), sizesFile)
  const probeRecord = {
    source: 'plugins/scripts/pack-image.mjs',
    generated_at: new Date().toISOString(),
    jsc_prelude: true,
    web: {
      record: 'web/web-build.json',
      source: webRecord.source,
      package: webRecord.package,
      package_version: webRecord.version,
      commit: webRecord.commit,
      dsh_version: webRecord.dsh_version,
      entry: webRecord.entry,
      entry_sha256: entrySha,
      index_sha256: indexSha,
    },
    image: {
      record: 'sizes.json',
      commit: image.dsh_commit,
      dsh_version: image.dsh_version,
      pin_commit: image.dsh_pin_commit,
      pin_version: image.dsh_pin_version,
      expected_commit: image.dsh_expected_commit,
      expected_version: image.dsh_expected_version,
      checkout_overridden: image.dsh_checkout_overridden === true,
      checkout: image.dsh_checkout,
    },
  }
  writeFileSync(probeFile, `${JSON.stringify(probeRecord, null, 2)}\n`)
}

function bundle(dest) {
  const webDir = join(dest, 'web')
  const { record: webRecord, entrySha, indexSha } = validateWeb(webDir)
  const sizesFile = join(dest, 'sizes.json')
  const image = validateImage(sizesFile)
  compare(webRecord, image, join(webDir, 'web-build.json'), sizesFile)
  // A no-force skip keeps the existing directory as the delivered asset set.
  // Metadata alone is not enough: every runtime file the page and python
  // worker load must still be present and non-empty, or the app boots into
  // 404s (web-boot.js) or a hung python3 command (tool-worker-python.js).
  for (const [file, what] of [
    ['worker-entry.js', 'Worker entry'],
    ['tool-worker-python.js', 'python tool worker'],
    ['workflow-isolate.js', 'workflow isolate'],
    ['index.html', 'minimal page'],
    ['boot.js', 'minimal boot'],
    ['web/index.html', 'Web page'],
    ['web/web-boot.js', 'Web boot module'],
    ['sizes.json', 'image sizes record'],
  ]) {
    requireFile(join(dest, file), what)
  }
  requireDir(join(webDir, 'assets'), 'Web assets')
  const imageFile = join(dest, 'image.tar.gz')
  requireFile(imageFile, 'image archive')
  const probeFile = join(dest, 'probe-bundle.json')
  requireFile(probeFile, 'probe bundle record')
  const probeRecord = readJson(probeFile, 'probe bundle record')
  if (probeRecord.web?.record !== 'web/web-build.json'
      || probeRecord.image?.record !== 'sizes.json') {
    fail(`${probeFile} does not name web/web-build.json and sizes.json`)
  }
  if (probeRecord.web.commit !== webRecord.commit
      || probeRecord.web.dsh_version !== webRecord.dsh_version
      || probeRecord.web.entry_sha256 !== entrySha
      || probeRecord.web.index_sha256 !== indexSha) {
    fail(`${probeFile} does not describe the staged Web page`)
  }
  if (probeRecord.image.commit !== image.dsh_commit
      || probeRecord.image.dsh_version !== image.dsh_version) {
    fail(`${probeFile} does not describe the staged image`)
  }
  process.stdout.write(
    `copy-bundle-assets: existing bundle is same-source ${webRecord.commit} (${webRecord.dsh_version})\n`,
  )
}

try {
  if (mode === 'facts') facts(args[0])
  else if (mode === 'same') same(args[0], args[1])
  else if (mode === 'probe') probe(args[0], args[1], args[2])
  else if (mode === 'bundle') bundle(args[0])
  else fail(`unknown verification mode: ${mode}`)
} catch (reason) {
  console.error(`copy-bundle-assets: ${reason instanceof Error ? reason.message : String(reason)}`)
  process.exit(1)
}
NODE

# The full Web page is built by scripts/ci/build-web-dist.sh. Reuse an already
# staged copy when no explicit dist was passed; the copy step below stages it
# beside the old bundle and swaps only after the whole set validates. A clean
# checkout without the Web build is still a valid legacy Worker staging
# (www/ + image + entry), so sim.sh and a fresh developer build do not fail in
# Xcode staging just because the optional full page has not been generated yet.
STAGE_WEB=0
if [ -z "$WEB_DIST" ] && [ -f "$DEST/web/index.html" ]; then
  WEB_DIST="$DEST/web"
fi
if [ -z "$WEB_DIST" ]; then
  echo "copy-bundle-assets: no full Web dist; staging the legacy Worker/www assets only (run scripts/ci/build-web-dist.sh for /static/web/index.html)" >&2
elif [ ! -d "$WEB_DIST" ]; then
  echo "copy-bundle-assets: Web dist not found: $WEB_DIST" >&2
  exit 2
else
  WEB_FACTS="$(node "$TMP/verify-bundle.mjs" facts "$WEB_DIST")" || exit 1
  WEB_COMMIT="$(printf '%s\n' "$WEB_FACTS" | sed -n '1p')"
  WEB_VERSION="$(printf '%s\n' "$WEB_FACTS" | sed -n '2p')"
  [ -n "$WEB_COMMIT" ] && [ -n "$WEB_VERSION" ] \
    || { echo "copy-bundle-assets: Web dist metadata is incomplete" >&2; exit 1; }
  STAGE_WEB=1
fi

# A no-force run may only skip when the bundle that will remain is itself one
# fully validated same-source set. Checking the temporary build outputs is not
# enough: build-web-dist.sh may already have written a new $DEST/web beside an
# old sizes.json/image.tar.gz, and exiting here would leave that mix in place.
# Without a Web dist there is no cross-source pair to validate, so the legacy
# staging keeps its original replace-only-with-force behaviour.
if [ "$FORCE" -eq 0 ] && [ -e "$DEST/worker-entry.js" ]; then
  if [ "$STAGE_WEB" -eq 0 ]; then
    echo "copy-bundle-assets: $DEST already has assets (pass --force to replace)" >&2
    exit 0
  fi
  if ! node "$TMP/verify-bundle.mjs" bundle "$DEST"; then
    echo "copy-bundle-assets: existing $DEST does not validate as one same-source bundle; pass --force to replace it" >&2
    exit 1
  fi
  DEST_FACTS="$(node "$TMP/verify-bundle.mjs" facts "$DEST/web")" || exit 1
  DEST_COMMIT="$(printf '%s\n' "$DEST_FACTS" | sed -n '1p')"
  DEST_VERSION="$(printf '%s\n' "$DEST_FACTS" | sed -n '2p')"
  DEST_PIN_COMMIT="$(printf '%s\n' "$DEST_FACTS" | sed -n '3p')"
  DEST_PIN_VERSION="$(printf '%s\n' "$DEST_FACTS" | sed -n '4p')"
  WEB_PIN_COMMIT="$(printf '%s\n' "$WEB_FACTS" | sed -n '3p')"
  WEB_PIN_VERSION="$(printf '%s\n' "$WEB_FACTS" | sed -n '4p')"
  if [ "$DEST_COMMIT" != "$WEB_COMMIT" ] || [ "$DEST_VERSION" != "$WEB_VERSION" ] \
      || [ "$DEST_PIN_COMMIT" != "$WEB_PIN_COMMIT" ] || [ "$DEST_PIN_VERSION" != "$WEB_PIN_VERSION" ]; then
    echo "copy-bundle-assets: existing bundle is $DEST_COMMIT ($DEST_VERSION) but the requested Web dist is $WEB_COMMIT ($WEB_VERSION); pass --force to replace it" >&2
    exit 1
  fi
  echo "copy-bundle-assets: $DEST already has verified same-source assets (pass --force to replace)" >&2
  exit 0
fi

NEED_BUILD=0
if [ -z "$WORKER_OUT" ] || [ -z "$IMAGE_OUT" ]; then
  NEED_BUILD=1
fi
if [ "$NEED_BUILD" -eq 1 ]; then
  if [ -z "$CHECKOUT" ] && [ -f "$HOME/.config/phone-dsh/dsh-checkout" ]; then
    CHECKOUT="$(sed -n '1p' "$HOME/.config/phone-dsh/dsh-checkout" | tr -d '\r')"
  fi
  if [ -z "$CHECKOUT" ] || [ ! -d "$CHECKOUT" ]; then
    echo "copy-bundle-assets: no DSH checkout: pass --checkout, set PDSH_DSH_CHECKOUT, or write ~/.config/phone-dsh/dsh-checkout" >&2
    exit 2
  fi
  CHECKOUT="$(cd "$CHECKOUT" && pwd -P)"
  export PDSH_DSH_CHECKOUT="$CHECKOUT"
  if [ ! -d "$PLUGIN_DIR/node_modules" ]; then
    echo "copy-bundle-assets: plugins/node_modules is missing; warm the plugin dependencies first" >&2
    exit 2
  fi
fi

if [ -z "$WORKER_OUT" ]; then
  # Without --worker-out the entry is compiled from $CHECKOUT itself, so this
  # is a third build input that must be the same clean/built checkout as the
  # Web page and image. Reuse the image packer's verifier instead of trusting
  # worker-entry/build.mjs' Worker-host existence check: otherwise a canonical
  # ~/.config checkout would silently stage an old Worker entry beside a new
  # Web page and image.
  echo "copy-bundle-assets: verifying Worker checkout $WEB_VERSION $WEB_COMMIT" >&2
  PDSH_DSH_CHECKOUT="$CHECKOUT" node "$PLUGIN_DIR/scripts/dsh-checkout.mjs" --verify \
    --commit "$WEB_COMMIT" --version "$WEB_VERSION" >&2 \
    || { echo "copy-bundle-assets: Worker checkout does not match the Web/image source; pass --worker-out for a separately verified build" >&2; exit 1; }
  echo "copy-bundle-assets: building the Worker entry bundle"
  node "$PLUGIN_DIR/worker-entry/build.mjs" --out "$TMP/worker-entry" >&2
  WORKER_OUT="$TMP/worker-entry"
fi
if [ -z "$IMAGE_OUT" ]; then
  # Python artifacts are resolved through scripts/ci/python-artifacts.sh: the
  # pair is built once into its cache and reused. A tree that does not carry
  # the helper (for example the staging regression suite's minimal fixture)
  # packs without CPython and says so; pass --without-python for the same
  # result without the notice.
  PYTHON_ARGS=()
  if [ "$WITHOUT_PYTHON" -eq 1 ]; then
    PYTHON_ARGS=(--without-python)
  elif [ -f "$ROOT/scripts/ci/python-artifacts.sh" ]; then
    PYTHON_DIR="$(bash "$ROOT/scripts/ci/python-artifacts.sh")"
    PYTHON_ARGS=(--python "$PYTHON_DIR")
  else
    echo "copy-bundle-assets: scripts/ci/python-artifacts.sh not found; packing the image without CPython" >&2
  fi
  # jq engine artifacts follow the same tolerant resolution as Python: the
  # helper builds/reuses the cache; a tree without it packs without jq.
  JQ_ARGS=()
  if [ "$WITHOUT_JQ" -eq 1 ]; then
    JQ_ARGS=(--without-jq)
  elif [ -f "$ROOT/scripts/ci/jq-artifacts.sh" ]; then
    JQ_DIR="$(bash "$ROOT/scripts/ci/jq-artifacts.sh")"
    JQ_ARGS=(--jq "$JQ_DIR")
  else
    echo "copy-bundle-assets: scripts/ci/jq-artifacts.sh not found; packing the image without the jq engine" >&2
  fi
  if [ "$STAGE_WEB" -eq 1 ]; then
    echo "copy-bundle-assets: packing the VFS image for DSH $WEB_VERSION $WEB_COMMIT" >&2
    ( cd "$PLUGIN_DIR" && node "$PLUGIN_DIR/scripts/pack-image.mjs" --out "$TMP/image" \
        --checkout "$CHECKOUT" --checkout-sha "$WEB_COMMIT" --checkout-version "$WEB_VERSION" \
        ${PYTHON_ARGS[@]+"${PYTHON_ARGS[@]}"} ${JQ_ARGS[@]+"${JQ_ARGS[@]}"} ) >&2
  else
    echo "copy-bundle-assets: packing the VFS image" >&2
    ( cd "$PLUGIN_DIR" && node "$PLUGIN_DIR/scripts/pack-image.mjs" --out "$TMP/image" \
        ${PYTHON_ARGS[@]+"${PYTHON_ARGS[@]}"} ${JQ_ARGS[@]+"${JQ_ARGS[@]}"} ) >&2
  fi
  IMAGE_OUT="$TMP/image"
fi

for required in "$WORKER_OUT/worker-entry.js" "$WORKER_OUT/tool-worker-python.js" \
                "$WORKER_OUT/workflow-isolate.js" "$WORKER_OUT/www/index.html" \
                "$WORKER_OUT/www/boot.js" "$IMAGE_OUT/image.tar.gz"; do
  if [ ! -s "$required" ]; then
    echo "copy-bundle-assets: missing or empty expected build output: $required" >&2
    exit 1
  fi
done
if [ "$STAGE_WEB" -eq 1 ]; then
  for required in "$WORKER_OUT/web-boot.js" "$IMAGE_OUT/sizes.json"; do
    if [ ! -s "$required" ]; then
      echo "copy-bundle-assets: missing or empty expected build output: $required" >&2
      exit 1
    fi
  done
fi

# The Web page and the image must come from one controlled checkout. `same`
# also validates the source Web bytes (entry/index sha, boot-tag order, every
# ./assets reference) before the stage exists, let alone before the old bundle
# is replaced.
if [ "$STAGE_WEB" -eq 1 ]; then
  node "$TMP/verify-bundle.mjs" same "$WEB_DIST" "$IMAGE_OUT/sizes.json" || exit 1
fi

# Assemble the complete replacement beside the destination. Only this stage is
# written until it has passed the post-stage validation below.
STAGE="$(mktemp -d "$(dirname "$DEST")/.worker-stage.XXXXXX")"
if [ -f "$DEST/.gitkeep" ]; then
  cp "$DEST/.gitkeep" "$STAGE/"
fi
# An empty `lazy/` is not copied by Xcode's folder reference. Keep a small
# marker so the app bundle always has the directory `PhoneDSHBundleLocation`
# requires (pack-image writes no shards when the image fits one archive).
mkdir -p "$STAGE/lazy"
printf '%s\n' \
  "lazy overlay shards are written by plugins/scripts/pack-image.mjs." \
  > "$STAGE/lazy/README.txt"

# The Web page lives at `/static/web/index.html`; its relative `./assets/*`
# references then resolve under `/static/web/assets/*`. `web-boot.js` sits
# beside that page because the injected tag is `./web-boot.js`.
if [ "$STAGE_WEB" -eq 1 ]; then
  WEB_DIST_ABS="$(cd "$WEB_DIST" && pwd)"
  mkdir -p "$STAGE/web"
  cp -R "$WEB_DIST_ABS/." "$STAGE/web/"
  cp "$WORKER_OUT/web-boot.js" "$STAGE/web/web-boot.js"
  cp "$WORKER_OUT/web-boot.js.map" "$STAGE/web/" 2>/dev/null || true
fi

# JavaScriptCore prelude (same shim as scripts/ci/smoke.sh): these
# definitions must exist before the Worker entry's module graph evaluates.
cat > "$TMP/javascriptcore-prelude.js" <<'PRELUDE'
// SPDX-License-Identifier: MIT
// Probe build compatibility prelude for JavaScriptCore platform gaps.
// See examples/probe-app/scripts/copy-bundle-assets.sh.
if (typeof Symbol.dispose === "undefined") {
  Object.defineProperty(Symbol, "dispose", {
    value: Symbol.for("xl.symbol.dispose"), configurable: true,
  });
}
if (typeof Symbol.asyncDispose === "undefined") {
  Object.defineProperty(Symbol, "asyncDispose", {
    value: Symbol.for("xl.symbol.asyncDispose"), configurable: true,
  });
}
if (typeof ReadableStream === "function"
    && typeof ReadableStream.prototype[Symbol.asyncIterator] !== "function") {
  ReadableStream.prototype[Symbol.asyncIterator] = function () {
    var reader = this.getReader();
    return {
      next: function () {
        return reader.read().then(function (result) {
          return result.done
            ? { done: true, value: undefined }
            : { done: false, value: result.value };
        });
      },
      return: function () {
        reader.cancel().catch(function () {});
        return Promise.resolve({ done: true, value: undefined });
      },
      throw: function (error) {
        reader.cancel(error).catch(function () {});
        return Promise.reject(error);
      },
    };
  };
}
PRELUDE
cat "$TMP/javascriptcore-prelude.js" "$WORKER_OUT/worker-entry.js" \
  > "$STAGE/worker-entry.js"
cp "$WORKER_OUT/worker-entry.js.map" "$STAGE/" 2>/dev/null || true
# The W7 python runtime spawns its dedicated tool worker beside the entry with
# `new URL('./tool-worker-python.js', import.meta.url)`. Staging it here is what
# makes python3 work in the probe app at all: without it the nested Worker 404s
# and every python3 command hangs instead of failing.
cp "$WORKER_OUT/tool-worker-python.js" "$STAGE/"
cp "$WORKER_OUT/tool-worker-python.js.map" "$STAGE/" 2>/dev/null || true
# `tool-worker.js` is the generic WASI worker; the jq toolbox spawns it at
# `new URL('./tool-worker.js', import.meta.url)`. A jq-less build (including a
# legacy prebuilt bundle) has no such file, so do not synthesize one.
if [ "$WITHOUT_JQ" -eq 0 ] && [ -f "$WORKER_OUT/tool-worker.js" ]; then
  cp "$WORKER_OUT/tool-worker.js" "$STAGE/"
  cp "$WORKER_OUT/tool-worker.js.map" "$STAGE/" 2>/dev/null || true
fi
# The Worker-native workflow bridge creates its dedicated isolate with
# `new URL('./workflow-isolate.js', location.href)`. Without this file the
# standard preset can mount but every workflow run fails at isolate startup.
cp "$WORKER_OUT/workflow-isolate.js" "$STAGE/"
cp "$WORKER_OUT/workflow-isolate.js.map" "$STAGE/" 2>/dev/null || true
cp "$WORKER_OUT/www/index.html" "$WORKER_OUT/www/boot.js" "$STAGE/"
cp "$IMAGE_OUT/image.tar.gz" "$STAGE/"
if [ -d "$IMAGE_OUT/lazy" ]; then
  cp -R "$IMAGE_OUT/lazy/." "$STAGE/lazy/"
fi
for extra in worker.js client.js manifest.json sizes.json; do
  if [ -f "$IMAGE_OUT/$extra" ]; then
    cp "$IMAGE_OUT/$extra" "$STAGE/"
  fi
done

if [ "$STAGE_WEB" -eq 1 ]; then
  # The staged page has to be self-consistent and its real build record must
  # describe these exact bytes. Nothing under $DEST is touched until this passes;
  # the probe bundle record names both sources by commit/version and is written
  # last.
  for required in "$STAGE/web/index.html" "$STAGE/web/web-boot.js" \
                  "$STAGE/web/web-build.json" "$STAGE/sizes.json"; do
    if [ ! -s "$required" ]; then
      echo "copy-bundle-assets: missing or empty staged asset: $required" >&2
      exit 1
    fi
  done
  if [ ! -d "$STAGE/web/assets" ] || [ -z "$(ls -A "$STAGE/web/assets" 2>/dev/null)" ]; then
    echo "copy-bundle-assets: missing or empty staged asset: $STAGE/web/assets" >&2
    exit 1
  fi
  node "$TMP/verify-bundle.mjs" probe "$STAGE/web" "$STAGE/sizes.json" \
    "$STAGE/probe-bundle.json" || exit 1
else
  # Legacy Worker/www staging has no Web page to cross-check; keep the small
  # audit record that names the packer and the JavaScriptCore prelude.
  printf '%s\n' \
    "{\"source\":\"plugins/scripts/pack-image.mjs\",\"generated_at\":\"$(date -u +%Y-%m-%dT%H:%M:%SZ)\",\"jsc_prelude\":true}" \
    > "$STAGE/probe-bundle.json"
fi
# Swap the validated stage into place with same-directory renames. If the
# second rename fails, put the previous bundle back; the old bundle is only
# removed after the replacement is complete.
if [ -e "$DEST" ]; then
  OLD="$(mktemp -d "$(dirname "$DEST")/.worker-old.XXXXXX")"
  rmdir "$OLD"
  mv "$DEST" "$OLD"
fi
if ! mv "$STAGE" "$DEST"; then
  if [ -n "$OLD" ]; then
    mv "$OLD" "$DEST"
    OLD=""
  fi
  echo "copy-bundle-assets: cannot replace $DEST with the staged bundle" >&2
  exit 1
fi
STAGE=""
if [ -n "$OLD" ]; then
  rm -rf "$OLD"
  OLD=""
fi

echo "copy-bundle-assets: wrote $(du -sh "$DEST" | awk '{print $1}') to $DEST" >&2
